let describe = global.get('describe', 'default');

let entries = msg.payload.split(',');
for (const i in entries) {
    let pair = entries[i].split('=');
    let valid = false;
    let id = pair[0];
    let label = id;
    let raw = pair[1];
    let val = raw;
    let full = raw;
    let unit = '';

    // get readbale label
	if (typeof describe.label[label] == 'string') {
        label = describe.label[label];
	}
    // get readbale unit
	if (typeof describe.unit[id] == 'string') {
        unit = describe.unit[id];
	}

	// Convert numeric value to number
	if (!isNaN(val) && isFinite(Number(val))) {
        val = Number(val);
    }

    if (id === 'pow') {
        full = describe.pow[raw];
        valid = true;
    }

    if (id === 'mode') {
        full = describe.mode[raw];
        valid = true;
    }

    if (id === 'stemp') {
        full = full + unit;
        valid = true;
    }

    if (id === 'f_rate') {
        full = describe.f_rate[raw];
        valid = true;
    }

    if (id === 'f_dir') {
        full = describe.f_dir[raw];
        valid = true;
    }

    // sensor
    if (id === 'htemp') {
        full = full + unit;
        valid = true;
    }

    // sensor
    if (id === 'otemp') {
        full = full + unit;
        valid = true;
    }

    if (valid === true) {
        node.send({
            'topic': msg.topic,
            'id': id,
            'payload': {
                'unit': unit,
                'label': label,
                'raw': raw,
                'val': val,
                'full': full
            }
        });
    }
}

return;

